package com.wizzadrds.theworldremembers.chronicle;
import net.minecraft.client.gui.GuiGraphicsExtractor; import net.minecraft.client.gui.components.Button; import net.minecraft.client.gui.screens.Screen; import net.minecraft.network.chat.Component; import java.util.*;
public final class ChronicleScreen extends Screen{private final List<List<String>> pages;private int page;public ChronicleScreen(String encoded){super(Component.literal("The World Remembers — Chronicles"));pages=parse(encoded);} private static List<List<String>> parse(String raw){var out=new ArrayList<List<String>>();var current=new ArrayList<String>();for(String line:raw.split("\\n",-1)){if(line.startsWith("---")&&line.endsWith("---")){out.add(current);current=new ArrayList<>();}else current.add(line);}out.add(current);while(out.size()<5)out.add(new ArrayList<>());return out;} @Override protected void init(){page=0;for(int i=0;i<5;i++){final int p=i;addRenderableWidget(Button.builder(Component.literal(new String[]{"Timeline","People","Relationships","Families","Villages"}[i]),b->page=p).bounds(15+i*110,40,100,20).build());}} @Override public void extractRenderState(GuiGraphicsExtractor g,int mouseX,int mouseY,float delta){super.extractRenderState(g,mouseX,mouseY,delta);g.centeredText(font,title,width/2,18,-1);var rows=pages.get(Math.min(page,pages.size()-1));int y=72;for(int i=0;i<Math.min(rows.size(),24);i++){String s=rows.get(i);if(s.length()>110)s=s.substring(0,107)+"...";g.text(font,s,24,y,0xE0E0E0,true);y+=12;}g.text(font,"Use the tabs above · Esc closes",24,height-24,0x888888,true);}}
